with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('skabe sig', 'phrase', '609a0cb6-bd56-5174-a909-1b76af198901', 1, 'verb', null, 'кривлятися, вередувати', 'Hun skaber sig altid når hun skal i seng.', 'Вона завжди вередує, коли їй треба лягати спати.'), ('køre sammen', 'phrase', '2ad026ac-3f74-569c-9bec-adfa2bb6af5c', 1, 'verb', null, 'зіткнутися (про транспорт)', 'Bussen og lastbilen kørte sammen i krydset.', 'Автобус і вантажівка зіткнулися на перехресті.'), ('køre ud', 'phrase', 'adfd3dd7-52e3-5851-8ac3-c9049ae29b51', 1, 'verb', null, 'виїжджати (з гаража, на дорогу)', 'Bilen kører ud fra garagen hver morgen.', 'Машина виїжджає з гаража щоранку.'), ('køre ud', 'phrase', '66a3069b-ac8a-5394-90bb-36b3ebf05a1b', 2, 'verb', null, 'розвозити (товари)', 'Vi kører ud med varer til kunderne om eftermiddagen.', 'Ми розвозимо товари клієнтам після обіду.'), ('følge op', 'phrase', '408d00df-2031-51ad-baa4-3428c1043699', 1, 'verb', null, 'продовжувати (розпочате)', 'Læreren fulgte op på elevernes spørgsmål efter timen.', 'Вчитель продовжив займатися запитаннями учнів після уроку.'), ('give sig til kende', 'phrase', '04c2deb7-8fff-57d6-bb5c-c9d1d102188a', 1, 'verb', null, 'давати про себе знати (проявлятися)', 'Sygdommen gav sig til kende med feber og træthed.', 'Хвороба проявлялася у вигляді гарячки та втоми.'), ('slå igen', 'phrase', 'bc71e3e7-749d-59e1-8ad2-ee1becaec1e2', 1, 'verb', null, 'давати здачі', 'Han slog igen, da de drillede ham.', 'Він дав здачі, коли його дражнили.'), ('slå ud', 'phrase', '26b71214-6253-5f85-8273-b289a37bc009', 1, 'verb', null, 'розпускатися (про квіти)', 'Roserne slog ud i haven i går.', 'Вчора в саду розквітли троянди.'), ('falde for', 'phrase', '2bac3c33-f362-5d63-8ddd-24ea85cdc53c', 1, 'verb', null, 'закохуватися (в когось)', 'Jeg faldt for hende med det samme.', 'Я одразу закохався в неї.'), ('falde for', 'phrase', '2f6b6afe-e25d-59a1-979f-b77560087ec9', 2, 'verb', null, 'попадатися (на обман)', 'Han falder for den samme undskyldning hver gang.', 'Він щоразу ведеться на ту саму відмовку.'), ('falde over', 'phrase', '2ebbbb1b-fabe-5e94-ab17-22593c655060', 1, 'verb', null, 'випадково натрапити (на щось)', 'Hun faldt over en gammel bog på loftet.', 'Вона натрапила на стару книгу на горищі.'), ('inden under', 'phrase', '13801b12-b403-5798-bf21-8399d3e5ba26', 1, 'preposition', null, 'під (чимось, всередині)', 'Katten gemmer sig inden under sofaen.', 'Кіт ховається під диваном.'), ('nå frem til', 'phrase', '9e05da9d-59c2-5969-9588-dbc9c83ea1e2', 1, 'verb', null, 'доходити до (висновку, згоди)', 'Vi nåede frem til en løsning efter lang tids diskussion.', 'Ми дійшли до рішення після тривалої розмови.'), ('lyde på', 'phrase', '543329ed-7ccb-5618-8fa2-78aa2ca0417b', 1, 'verb', null, 'складати (про суму, рахунок)', 'Regningen lød på tre hundrede kroner.', 'Рахунок складав триста крон.'), ('stige ned', 'phrase', '2137ed53-b071-57af-a74e-93aab768d439', 1, 'verb', null, 'спускатися (вниз)', 'Han steg ned ad trappen med en tung kuffert.', 'Він спустився сходами з важкою валізою.'), ('betale af', 'phrase', '0b53614f-d31d-5b22-95db-7112a34b22a3', 1, 'verb', null, 'виплачувати (борг)', 'Jeg betaler af på mit lån hver måned.', 'Я щомісяця погашаю свій кредит.'), ('køre videre', 'phrase', '4f0156c3-964d-52e5-92ae-48b4abd74f16', 1, 'verb', null, 'їхати далі', 'Vi kører videre mod nord efter frokost.', 'Після обіду ми їдемо далі на північ.'), ('forsøge sig', 'phrase', 'add80b5a-7fd4-595a-96e7-a51966e013a7', 1, 'verb', null, 'спробувати свої сили (у чомусь)', 'Hun vil gerne forsøge sig som forfatter.', 'Вона хотіла б спробувати себе в письменництві.'), ('gøre det kort', 'phrase', 'f455e403-2a2c-5ac1-a6c6-fe0b73fd6e3c', 1, 'verb', null, 'бути стислим', 'Jeg gør det kort, fordi jeg har travlt.', 'Я буду стислим, бо зайнятий.'), ('ligge stille', 'phrase', 'ffdb061c-f785-542b-ad6c-99c376f8e059', 1, 'verb', null, 'лежати нерухомо', 'Hunden ligger stille på gulvet.', 'Собака нерухомо лежить на підлозі.'), ('sidde stille', 'phrase', '8e3b74e1-aa34-5d53-980b-c56135024ffe', 1, 'verb', null, 'сидіти спокійно (не рухатися)', 'Børnene sad stille og lyttede til historien.', 'Діти сиділи тихо і слухали історію.'), ('bag på', 'phrase', '62dcf3cf-2cdf-5881-9a12-36fa87b820c2', 1, 'preposition', null, 'ззаду на (чомусь)', 'Der er en plet bag på skjorten.', 'На спині сорочки є пляма.'), ('stå bag', 'phrase', 'eeea1fa8-ecf1-5e01-8c3f-3ae3e40543a1', 1, 'verb', null, 'підтримувати (когось)', 'Hun står bag sin ven i svære tider.', 'Вона підтримує свою подругу у важкі часи.'), ('stå bag', 'phrase', '41d53e58-5f1d-5be8-a3d0-1c9b71a64365', 2, 'verb', null, 'стояти за (чимось, бути причиною)', 'Politiet tror, at en gruppe står bag tyveriet.', 'Поліція вважає, що за крадіжкою стоїть група.'), ('trække sig ud', 'phrase', '8f5d7ad9-bfbe-5c71-8c6c-ee2795bc03c7', 1, 'verb', null, 'виходити (зі складу, участі)', 'Virksomheden trak sig ud af samarbejdet i sidste uge.', 'Минулого тижня компанія вийшла з цієї співпраці.'), ('trække sig ud', 'phrase', '56910bd9-79a4-59c2-880b-2c2bfc6cb054', 2, 'verb', null, 'затягуватися (про час)', 'Mødet trak sig ud og varede over tre timer.', 'Зустріч затягнулася і тривала понад три години.'), ('holde fast i', 'phrase', '5bda9fd2-0d4a-55e7-8f18-53852dfafab6', 1, 'verb', null, 'твердо триматися (думки, рішення)', 'Han holdt fast i sin mening under mødet.', 'На зустрічі він не відступив від своєї думки.'), ('køre fast', 'phrase', '1bd66e81-9d1e-5e83-8dc6-07a7e32d9299', 1, 'verb', null, 'застрягати (про транспорт)', 'Bilen kørte fast i mudderet.', 'Машина застрягла в багнюці.'), ('køre fast', 'phrase', '1503d90f-27f4-53b6-b150-1b504f1d8169', 2, 'verb', null, 'зациклюватися (про людину, розмову)', 'Mødet kører fast i detaljer.', 'Зустріч застрягає в деталях.'), ('sætte sig fast', 'phrase', '053fe92f-518a-5722-a1bd-4a77fa4936b6', 1, 'verb', null, 'застрягати', 'Bilen satte sig fast i mudderet.', 'Машина застрягла в багнюці.'), ('bo for sig selv', 'phrase', '81ece2d8-44ab-56f1-85fe-b2c7d65d481b', 1, 'verb', null, 'жити окремо (самостійно)', 'Min datter bor for sig selv i København.', 'Моя донька живе сама в Копенгагені.'), ('bo sammen', 'phrase', 'a03dbb42-b3fd-54da-a220-74b39e5f7699', 1, 'verb', null, 'жити разом (з кимось)', 'De bor sammen i en lille lejlighed.', 'Вони живуть разом у маленькій квартирі.'), ('være til hjælp', 'phrase', '1d05f67f-31a6-553a-bac0-82d734f96c31', 1, 'verb', null, 'допомагати', 'Hans råd var til hjælp for mig.', 'Його поради були для мене корисними.'), ('give hånd', 'phrase', '64c31d20-fc48-5106-a960-cba80f00ba3b', 1, 'verb', null, 'потискати руку', 'De gav hånd, da de mødtes.', 'Вони потиснули руки, коли зустрілися.'), ('flytte sammen', 'phrase', 'f8c10d9c-fd97-5f55-af01-2f74c8731c0d', 1, 'verb', null, 'з''їжджатися (починати жити разом)', 'De flyttede sammen efter et halvt år.', 'Вони з''їхалися через шість місяців.'), ('få til opgave', 'phrase', '3d54cb47-b993-5d17-b8e5-ccaa3ec6588c', 1, 'verb', null, 'отримувати завдання', 'Hun fik til opgave at rydde op på værelset.', 'Їй доручили прибрати кімнату.'), ('ændre ved', 'phrase', '9d8838af-a4d3-51df-877f-312a782737d4', 1, 'verb', null, 'змінювати (щось)', 'De ændrede ved aftalen i sidste øjeblik.', 'Вони змінили угоду в останню хвилину.'), ('rette op på', 'phrase', 'bab5047f-25a8-5dde-91df-cc149fa67766', 1, 'verb', null, 'виправляти (помилку чи ситуацію)', 'Han rettede op på fejlen med det samme.', 'Він одразу виправив помилку.'), ('rette sig efter', 'phrase', 'c31c867c-2a03-54da-b2c2-1884f4718f64', 1, 'verb', null, 'дотримуватися (правил), підлаштовуватися', 'Jeg retter mig efter de nye regler på arbejdet.', 'Я дотримуюся нових правил на роботі.'), ('rette sig mod', 'phrase', 'fd8deddb-1edd-5dd7-b434-487afa0cd031', 1, 'verb', null, 'бути спрямованим на', 'Kritikken retter sig mod regeringens plan.', 'Критика спрямована на план уряду.'), ('rette sig mod', 'phrase', 'dddf40df-840d-5567-90a0-00abc9b7928a', 2, 'verb', null, 'звертатися до (когось)', 'Spørgsmålet retter sig mod alle forældre.', 'Питання адресоване всім батькам.'), ('vende sig til', 'phrase', '21c13d50-4aaa-5a43-a9a6-75e279974c31', 1, 'verb', null, 'звикати (до чогось)', 'Jeg vender mig til den nye rutine.', 'Я звикаю до нової рутини.'), ('have øje for', 'phrase', 'a77ae29d-e718-5178-93e2-fb47ec6d4868', 1, 'verb', null, 'помічати, звертати увагу на', 'Hun har øje for detaljerne i maleriet.', 'Вона помічає деталі картини.'), ('være længe om', 'phrase', '3047812d-0f1c-51bc-ab3a-70224160b450', 1, 'verb', null, 'довго робити (щось)', 'Han er længe om at spise morgenmad.', 'Він довго снідає.'), ('åbne sig', 'phrase', '208e04e9-6c57-5313-9982-b1e09946bef3', 1, 'verb', null, 'відчинятися (про двері, вікно)', 'Døren åbnede sig langsomt.', 'Двері повільно відчинилися.'), ('åbne sig', 'phrase', '9696c790-01d0-531f-b6d7-7b0bdac4699e', 2, 'verb', null, 'відкриватися (ділитися почуттями)', 'Hun åbner sig aldrig for fremmede.', 'Вона ніколи не відкривається незнайомцям.'), ('se igennem', 'phrase', 'cd1a3c7c-d8b5-52fe-8811-863df9ec977e', 1, 'verb', null, 'переглядати (побіжно перевіряти)', 'Jeg ser igennem dokumenterne inden mødet.', 'Я переглядаю документи перед зустріччю.'), ('se igennem', 'phrase', '79be4513-986e-587b-8346-4453ebeb6cfc', 2, 'verb', null, 'переглядати (шукати щось)', 'Hun så igennem bunken for at finde kvitteringen.', 'Вона переглянула купу, щоб знайти чек.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0012' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
